query TournamentStatQuery($id: Int!, $limit: Int!, $offset: Int!) {
  member(id: $id) {
    id
    playerTournaments(limit: $limit, offset: $offset) {
      ... on TeamPlayerTournament {
        __typename
        id
        teamNumber
        skillLevel
        standing
        teamName
        disqualified
        tournament {
          name
          id
          startTime
          type: formatType
          __typename
        }
      }
      ... on SinglesPlayerTournament {
        id
        skillLevel
        standing
        disqualified
        tournament {
          name
          id
          startTime
          type: formatType
          __typename
        }
        __typename
      }
      ... on USAMPlayerTournament {
        id
        standing
        disqualified
        tournament {
          id
          name
          startTime
          type: formatType
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
